https://alpine.global.ssl.fastly.net/alpine/latest-stable/community
EOAPK
echo '[lattice] APK mirror: alpine.global.ssl.fastly.net'

# -- 5. Packages (slots[5..15] bit-select) --
echo '[lattice] Installing: python3 curl htop bash vim jq git openssl ncurses file'
apk update -q 2>/dev/null && apk add -q python3 curl htop bash vim jq git openssl ncurses file 2>/dev/null
